/**
 * Local guitar chord library.
 *
 * Serves the same chord dictionary the hosted backend served from Postgres, now as
 * static per-key JSON files under /chords/guitar/ (generated by
 * scripts/sync-guitar-chords-json.js from the szaza dataset + project augmentations).
 *
 * Semantics preserved from ChordLibraryService (backend):
 * - exact normalized-symbol match, then enharmonic fallback (A# <-> Bb etc.)
 * - voicings ordered by original position index
 * - names "Voicing N" when a chord has more than one voicing
 * - ids are deterministic (`gtr:<normalizedSymbol>:<index>`) instead of per-seed UUIDs,
 *   so getVoicingById keeps working for stored song voicing references. Hosted-era UUIDs
 *   predate this scheme and cannot be resolved (the mapping table is gone).
 */

export interface LocalChordData {
  frets?: number[];
  fingers?: number[];
  barres?: number[];
  baseFret?: number;
  capo?: boolean;
  notes?: string[];
}

export interface LocalLibraryVoicing {
  id: string;
  chord: LocalChordData;
  name?: string;
  source?: string;
}

type KeyFile = Record<string, Array<{ id: string; name?: string; chord: LocalChordData }>>;

const BASE_URL = '/provenance-v2/chords/guitar';

const SHARP_TO_FILE: Record<string, string> = {
  'C#': 'Csharp',
  'D#': 'Dsharp',
  'F#': 'Fsharp',
  'G#': 'Gsharp',
  'A#': 'Asharp',
};
const FLAT_TO_SHARP: Record<string, string> = {
  Db: 'C#',
  Eb: 'D#',
  Gb: 'F#',
  Ab: 'G#',
  Bb: 'A#',
};
const SHARP_TO_FLAT: Record<string, string> = {
  'C#': 'Db',
  'D#': 'Eb',
  'F#': 'Gb',
  'G#': 'Ab',
  'A#': 'Bb',
};

function chordRoot(symbol: string): string | null {
  const m = symbol.match(/^([A-G][#b]?)/);
  return m ? m[1] : null;
}

/** The single file that can contain a symbol: keyed by canonical (sharp) root. */
function fileKeyForRoot(root: string): string {
  const canonical = FLAT_TO_SHARP[root] ?? root;
  return SHARP_TO_FILE[canonical] ?? canonical;
}

/** Port of the backend's toEnharmonicSymbol: swap root spelling, keep the rest. */
export function enharmonicSymbol(symbol: string): string {
  const root = chordRoot(symbol);
  if (!root) return symbol;
  const rest = symbol.slice(root.length);
  if (root.endsWith('#') && SHARP_TO_FLAT[root]) return SHARP_TO_FLAT[root] + rest;
  if (root.endsWith('b') && FLAT_TO_SHARP[root]) return FLAT_TO_SHARP[root] + rest;
  return symbol;
}

const keyCache = new Map<string, KeyFile>();
const keyPending = new Map<string, Promise<KeyFile | null>>();

function loadKeyFile(fileKey: string): Promise<KeyFile | null> {
  const cached = keyCache.get(fileKey);
  if (cached) return Promise.resolve(cached);
  let pending = keyPending.get(fileKey);
  if (!pending) {
    pending = fetch(`${BASE_URL}/${fileKey}.json`)
      .then((res) => {
        if (!res.ok) throw new Error(`guitar chords ${fileKey}: ${res.status}`);
        return res.json() as Promise<KeyFile>;
      })
      .then((data) => {
        keyCache.set(fileKey, data);
        return data;
      })
      .catch(() => null);
    keyPending.set(fileKey, pending);
  }
  return pending;
}

function withSource(list: Array<{ id: string; name?: string; chord: LocalChordData }>): LocalLibraryVoicing[] {
  return list.map((v) => ({ id: v.id, name: v.name, chord: v.chord, source: 'szaza' }));
}

/**
 * All library guitar voicings for a normalized chord symbol (e.g. "Cmaj7", "Am", "G", "C/E").
 * Tries the exact symbol, then its enharmonic spelling - same order as the backend.
 */
export async function getGuitarVoicings(normalizedSymbol: string): Promise<LocalLibraryVoicing[]> {
  const root = chordRoot(normalizedSymbol);
  if (!root) return [];
  const data = await loadKeyFile(fileKeyForRoot(root));
  if (!data) return [];
  const direct = data[normalizedSymbol];
  if (direct?.length) return withSource(direct);
  const alt = enharmonicSymbol(normalizedSymbol);
  if (alt !== normalizedSymbol) {
    const fallback = data[alt];
    if (fallback?.length) return withSource(fallback);
  }
  return [];
}

const VOICING_ID_RE = /^gtr:(.+):(\d+)$/;

/** Resolve a deterministic library voicing id back to its voicing, or null. */
export async function getGuitarVoicingById(id: string): Promise<LocalLibraryVoicing | null> {
  const m = id.match(VOICING_ID_RE);
  if (!m) return null;
  const symbol = m[1];
  const index = parseInt(m[2], 10);
  const list = await getGuitarVoicings(symbol);
  return list[index] ?? null;
}

/* Test hooks: preload key data without fetch. */
export function __registerKeyData(fileKey: string, data: KeyFile): void {
  keyCache.set(fileKey, data);
}
export function __clearChordLibraryCache(): void {
  keyCache.clear();
  keyPending.clear();
}
